    """
    Generates a string of length (n+1) with digits s_0s_1\ldots s_n, defined as follows.
    For each i = 0, 1, 2, \ldots, N,
    - if there is a divisor j of N that is between 1 and 9, inclusive, and i is a multiple of N/j, then s_i is the digit corresponding to the smallest such j (s_i will thus be one of 1, 2, ..., 9);
    - if no such j exists, then s_i is -.
    """
    for i in range(1, N+1):
        if i % N == 0:
            s_i = 1
        elif i % N == 1:
            s_i = 2
        elif i % N == 2:
            s_i = 3
        elif i % N == 3:
            s_i = 4
        elif i % N == 4:
            s_i = 5
        elif i % N == 5:
            s_i = 6
        elif i % N == 6:
            s_i = 7
        elif i % N == 7:
            s_i = 8
        elif i % N == 8:
            s_i = 9
        elif i % N == 9:
            s_i = -1
    return s_i

