def maximize_min_deliciousness(n, a_i, c_i):
    max_deliciousness = 0
    for i in range(n):
        for j in range(1, n):
            if a_i == c_i:
                max_deliciousness = max(max_deliciousness, a_i)
            else:
                max_deliciousness = max(max_deliciousness, c_i)
    return max_deliciousness

